  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   *   Atomically moves an entity (Player or Box) from a `from` cell to a `to`
   *   cell, updating the entities map and appending the change to the current
   *   GameStateTransition. If a box is pushed (i.e., the move pushes a Box),
   *   the move automatically calls checkpoint() so that the transition can be
   *   undone later as a single atomic step.
   * Algorithm:
   *   1. Validate `from` and `to` are in-bounds and `from` is not empty.
   *   2. Determine the entity at `from` (must be a Player or Box).
   *   3. If a Box is at `to`:
   *       a. Reject the move unless the box's playerId matches the moving
   *          player's id and the cell beyond the box is Empty.
   *       b. Move the box from `to` to beyond-to (one further cell in the
   *          same direction), recording both moves in currentTransition.
   *   4. Move the player (or box) from `from` to `to`; record in
   *      currentTransition via transition.add(from, to).
   *   5. If a box was pushed (i.e., transition contains at least a box move):
   *       call checkpoint() to push the transition onto history and reset
   *       currentTransition.
   * Related Features:
   *   - GameState.entities
   *   - GameState.currentTransition
   *   - GameState.history
   * Related Classes:
   *   GameStateTransition, TransitionStack, Player, Box, Empty, Wall, Entity,
   *   EntityMap, Position
   * Input:
   *   - from : Position
   *       Source cell (must currently contain a movable entity).
   *   - to   : Position
   *       Destination cell.
   * Output:
   *   - void
   * Pre-condition:
   *   - `from` and `to` must be in-bounds.
   *   - The move must be legal under game rules (handled by caller; this
   *     method assumes the preconditions are met and throws IllegalStateException
   *     otherwise).
   * Post-condition:
   *   - entities reflects the new positions.
   *   - If a box was pushed, history gains a new checkpoint; currentTransition
   *     is reset to empty.
   *   - If no box was pushed, currentTransition is non-empty and awaiting more
   *     moves until next checkpoint.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void move(final Position from, final Position to)
  {
    // 1. Validate `from` and `to` are in-bounds and `from` is not empty.
    if (from == null || to == null)
    {
      throw new IllegalStateException("from and to must be non-null");
    }
    if (getEntity(from) == null)
    {
      throw new IllegalStateException("`from` cell is empty or out of bounds");
    }

    // 2. Determine the entity at `from` (must be a Player or Box).
    Entity mover = getEntity(from);
    boolean boxPushed = false;

    // 3. If a Box is at `to`:
    Entity atTo = getEntity(to);
    if (atTo instanceof Box)
    {
      // a. Reject the move unless the box's playerId matches the moving
      //    player's id and the cell beyond the box is Empty.
      if (!(mover instanceof Player))
      {
        throw new IllegalStateException("Only a player can push a box");
      }
      Box boxAtTo = (Box) atTo;
      Player playerMover = (Player) mover;
      if (boxAtTo.getPlayerId() != playerMover.getId())
      {
        throw new IllegalStateException("Box's playerId does not match the moving player's id");
      }
      // Compute beyond-to (one further cell in the same direction).
      int dx = Integer.signum(to.getX() - from.getX());
      int dy = Integer.signum(to.getY() - from.getY());
      Position beyond = Pa22Factory.eINSTANCE.createPosition();
      beyond.setX(to.getX() + dx);
      beyond.setY(to.getY() + dy);
      Entity beyondEntity = getEntity(beyond);
      if (!(beyondEntity instanceof Empty))
      {
        throw new IllegalStateException("The cell beyond the box is not Empty");
      }

      // Ensure currentTransition exists.
      GameStateTransition transition = getCurrentTransition();
      if (transition == null)
      {
        transition = Pa22Factory.eINSTANCE.createGameStateTransition();
        setCurrentTransition(transition);
      }

      // b. Move the box from `to` to beyond-to, recording both moves in
      //    currentTransition.
      transition.add(to, beyond);
      transition.add(from, to);
      boxPushed = true;
    }
    else
    {
      // 4. Move the player (or box) from `from` to `to`; record in
      //    currentTransition via transition.add(from, to).
      GameStateTransition transition = getCurrentTransition();
      if (transition == null)
      {
        transition = Pa22Factory.eINSTANCE.createGameStateTransition();
        setCurrentTransition(transition);
      }
      transition.add(from, to);
    }

    // 5. If a box was pushed, call checkpoint().
    if (boxPushed)
    {
      checkpoint();
    }
  }

